<template>
	<view class="privacy-page">
		<view class="fixed-header" :style="{ paddingTop: statusBarHeight + 'px' }">
			<view class="nav-bar">
				<view class="back-btn" @click="goBack">‹</view>
				<text class="nav-title">隐私设置</text>
				<view class="placeholder"></view>
			</view>
		</view>

		<scroll-view class="privacy-scroll" scroll-y enhanced :show-scrollbar="false" :style="{ paddingTop: headerHeight + 'px' }">
			<view class="settings-card">
				<view v-for="item in settings" :key="item.key" class="setting-row" @click="toggleSetting(item)">
					<view class="setting-main">
						<text class="setting-title">{{ item.title }}</text>
						<text class="setting-desc">{{ item.desc }}</text>
					</view>
					<view class="switch" :class="{ active: item.enabled }"><text></text></view>
				</view>
			</view>

			<view class="danger-card">
				<view class="danger-row" @click="goBlacklist">
					<text>黑名单</text>
					<text class="arrow">›</text>
				</view>
				<view class="danger-row" @click="showToast('举报记录稍后接入')">
					<text>举报处理记录</text>
					<text class="arrow">›</text>
				</view>
			</view>
		</scroll-view>
	</view>
</template>

<script>
export default {
	data() {
		return {
			statusBarHeight: 44,
			headerHeight: 96,
			settings: [
				{ key: 'recommend', title: '允许被推荐', desc: '关闭后不会出现在遇见页推荐的人里', enabled: true },
				{ key: 'strangerLetter', title: '允许陌生人写信', desc: '关闭后只有互相关注的人可以给你写信', enabled: true },
				{ key: 'namedNote', title: '纸条展示真实资料', desc: '纸条会展示头像昵称，便于对方了解你', enabled: true, locked: true },
				{ key: 'mutualMessage', title: '互关后允许私信', desc: '互相关注默认开启普通私信连接', enabled: true }
			]
		};
	},
	onLoad() {
		this.setHeaderHeight();
	},
	methods: {
		setHeaderHeight() {
			try {
				const info = uni.getSystemInfoSync();
				this.statusBarHeight = info.statusBarHeight || 44;
				const rpxToPx = (info.windowWidth || 375) / 750;
				this.headerHeight = this.statusBarHeight + Math.round(96 * rpxToPx);
			} catch (error) {
				this.headerHeight = 96;
			}
		},
		showToast(title) {
			uni.showToast({ title, icon: 'none' });
		},
		toggleSetting(item) {
			if (item && item.locked) {
				this.showToast('纸条默认实名展示');
				return;
			}
			item.enabled = !item.enabled;
		},
		goBlacklist() {
			uni.navigateTo({ url: '/pages/settings/blacklist' });
		},
		goBack() {
			uni.navigateBack();
		}
	}
};
</script>

<style lang="scss" scoped>
.privacy-page {
	min-height: 100vh;
	background: #f7f3f6;
}

.fixed-header {
	position: fixed;
	top: 0;
	left: 0;
	right: 0;
	z-index: 10;
	background: rgba(255, 255, 255, 0.97);
	border-bottom: 1rpx solid #f0e5ea;
}

.nav-bar {
	position: relative;
	display: flex;
	align-items: center;
	justify-content: space-between;
	height: 96rpx;
	padding: 0 28rpx;
}

.back-btn,
.placeholder {
	width: 72rpx;
	height: 72rpx;
}

.back-btn {
	display: flex;
	align-items: center;
	justify-content: center;
	font-size: 52rpx;
	color: #33262e;
}

.nav-title {
	position: absolute;
	left: 150rpx;
	right: 150rpx;
	text-align: center;
	font-size: 32rpx;
	font-weight: 700;
	color: #221820;
}

.privacy-scroll {
	height: 100vh;
}

.settings-card,
.danger-card {
	margin: 24rpx;
	border-radius: 24rpx;
	background: #ffffff;
	box-shadow: 0 10rpx 28rpx rgba(90, 55, 76, 0.05);
	overflow: hidden;
}

.setting-row,
.danger-row {
	display: flex;
	align-items: center;
	justify-content: space-between;
	gap: 22rpx;
	padding: 28rpx;
}

.setting-row + .setting-row,
.danger-row + .danger-row {
	border-top: 1rpx solid #f1ecef;
}

.setting-main {
	flex: 1;
	min-width: 0;
}

.setting-title,
.danger-row {
	font-size: 28rpx;
	font-weight: 700;
	color: #241b22;
}

.setting-desc {
	display: block;
	margin-top: 8rpx;
	font-size: 22rpx;
	line-height: 1.55;
	color: #9c8c95;
}

.switch {
	position: relative;
	width: 94rpx;
	height: 54rpx;
	border-radius: 999rpx;
	background: #e8e1e5;
	flex-shrink: 0;
}

.switch text {
	position: absolute;
	top: 6rpx;
	left: 6rpx;
	width: 42rpx;
	height: 42rpx;
	border-radius: 50%;
	background: #ffffff;
	box-shadow: 0 4rpx 12rpx rgba(0, 0, 0, 0.12);
	transition: transform 0.2s ease;
}

.switch.active {
	background: #d4688a;
}

.switch.active text {
	transform: translateX(40rpx);
}

.arrow {
	color: #b9aab2;
	font-size: 38rpx;
}
</style>
